mapper.select:
SELECT  
WHERE p.use_yn='Y'
  AND coalesce(p.prfm_bgn_dt,p.cntrct_bgn_dt) <= to_date(#{from},'YYYY-MM')+interval '1 year'-interval '1 day'
  AND coalesce(p.cur_end_dt,p.cntrct_end_dt) >= to_date(#{from},'YYYY-MM')
AND p.cntrct_ty_cd=#{type}
AND p.bsn_part_id=#{partId}
AND p.prj_stts_cd=#{status}
AND (strpos(lower(p.prj_nm),lower(#{q}))>0 OR strpos(lower(p.prj_no),lower(#{q}))>0)
ORDER BY p.prj_id

SELECT sum(m.aloc_amt)::bigint FROM prj.tk_aloc_line l
JOIN prj.tk_aloc_mth m ON m.aloc_line_id=l.aloc_line_id
WHERE l.prj_id=#{id} AND m.aloc_ym BETWEEN #{from} AND #{month}
  AND l.aloc_stg_cd=(SELECT x.aloc_stg_cd FROM prj.tk_aloc_line x WHERE x.prj_id=#{id}
    ORDER BY CASE x.aloc_stg_cd WHEN 'ACTUAL' THEN 0 WHEN 'FINAL' THEN 1 ELSE 2 END LIMIT 1)
